/// Generates `_mysoc_validator_fast.pyi` from the pyo3-stub-gen annotations in lib.rs.
///
/// Run from the workspace root:
///   cargo run --manifest-path mysoc_validator_fast/Cargo.toml --bin stub_gen
///
/// The output file is written to the Python package directory alongside the
/// compiled extension module.
fn main() -> pyo3_stub_gen::Result<()> {
    // stub_info() is generated by define_stub_info_gatherer! in lib.rs
    let stub = _mysoc_validator_fast::stub_info()?;
    stub.generate()?;
    Ok(())
}
